'''视觉原语（point/box/polygon/mask）与文本 token 的统一混合序列建模。

三件事：坐标离散化把几何回归变成分类；文本与原语块拼成一条序列做自回归
p(x)=prod_t p(x_t | x 的前缀)；用规范形与约束解码保证几何合法、可反解。
纯标准库实现，直接运行，末尾自带断言自测。
'''
import math

BINS = 1000
TAGS = {'point': '<point>', 'box': '<box>', 'polygon': '<polygon>', 'mask': '<mask>'}
CLOSE = '</prim>'
ARITY = {'point': 2, 'box': 4}


def quantize(c, bins=BINS):
    '''把 [0,1] 的连续坐标映射成桶号；越界 clamp，NaN/inf 直接报错。'''
    if bins < 2:
        raise ValueError('bins 至少为 2，否则反量化会除零')
    if not math.isfinite(c):
        raise ValueError('坐标必须是有限数: %r' % (c,))
    q = int(round(max(0.0, min(1.0, c)) * (bins - 1)))
    return max(0, min(bins - 1, q))


def dequantize(q, bins=BINS):
    '''桶号 -> [0,1] 坐标，误差上界 1/(2*(bins-1))。'''
    if bins < 2 or not 0 <= q <= bins - 1:
        raise ValueError('桶号越界或 bins 非法: %r / %r' % (q, bins))
    return q / (bins - 1)


def canon_box(box):
    '''任意角点顺序 -> 唯一表示（x1<=x2 且 y1<=y2），4 种写法收敛成 1 种。'''
    x1, y1, x2, y2 = box
    return (min(x1, x2), min(y1, y2), max(x1, x2), max(y1, y2))


def area2(poly):
    '''鞋带公式的两倍有向面积，正数表示逆时针。'''
    s = 0.0
    n = len(poly)
    for i in range(n):
        x1, y1 = poly[i]
        x2, y2 = poly[(i + 1) % n]
        s += x1 * y2 - x2 * y1
    return s


def canon_polygon(poly):
    '''去相邻重复点 -> 逆时针 -> 以字典序最小顶点为起点，2K 种写法收敛成 1 种。'''
    pts = []
    for p in poly:
        if not pts or tuple(p) != pts[-1]:
            pts.append(tuple(p))
    if len(pts) > 1 and pts[0] == pts[-1]:
        pts.pop()
    if len(pts) < 3:
        raise ValueError('多边形至少需要 3 个不重复顶点: %r' % (poly,))
    if area2(pts) < 0:
        pts = [pts[0]] + pts[:0:-1]
    k = min(range(len(pts)), key=lambda i: pts[i])
    return tuple(pts[k:] + pts[:k])


def rle_encode(bits):
    '''二值掩码（行优先展平）-> 段长；约定第 0 段是 0 的个数，前导 1 补长度 0。'''
    if not bits:
        return ()
    counts = []
    cur = bits[0]
    if cur == 1:
        counts.append(0)
    run = 0
    for b in bits:
        if b == cur:
            run += 1
        else:
            counts.append(run)
            cur = b
            run = 1
    counts.append(run)
    return tuple(counts)


def rle_decode(counts, total=None):
    '''段长 -> 二值掩码；total 给定时右侧补 0，超出尺寸则报错。'''
    bits = []
    val = 0
    for c in counts:
        if c < 0:
            raise ValueError('RLE 段长不能为负: %r' % (c,))
        bits.extend([val] * c)
        val ^= 1
    if total is not None:
        if len(bits) > total:
            raise ValueError('RLE 解出 %d 位，超过掩码尺寸 %d' % (len(bits), total))
        bits.extend([0] * (total - len(bits)))
    return bits


def prim_to_tokens(kind, geom):
    '''一个几何原语 -> 结构 token 块：标签 + 顶点数或 RLE + 坐标 token + 结束符。'''
    if kind == 'mask':
        return [TAGS['mask']] + ['<r%d>' % c for c in geom] + [CLOSE]
    if kind == 'polygon':
        pts = canon_polygon(geom)
        flat = [v for p in pts for v in p]
        head = [TAGS['polygon'], '<k%d>' % len(pts)]
        return head + ['<c%d>' % quantize(v) for v in flat] + [CLOSE]
    if kind not in ARITY:
        raise ValueError('未知原语类型: %r' % (kind,))
    box = canon_box(geom) if kind == 'box' else tuple(geom)
    return [TAGS[kind]] + ['<c%d>' % quantize(v) for v in box] + [CLOSE]


def encode(text_tokens, prims):
    '''文本 token 与所有原语块拼成一条混合序列，它就是生成问题里的 x。'''
    seq = list(text_tokens)
    for kind, geom in prims:
        seq.extend(prim_to_tokens(kind, geom))
    return seq


def _read_block(tokens, i):
    '''从 i 往后读到结束符，返回 (块体, 下一位置)；缺结束符说明序列被截断。'''
    j = i
    while j < len(tokens) and tokens[j] != CLOSE:
        j += 1
    if j >= len(tokens):
        raise ValueError('原语块缺少结束符 %s' % CLOSE)
    return tokens[i:j], j + 1


def parse_prim(tag, body):
    '''把块体还原成 (类型, 几何量)，顺带做结构合法性检查。'''
    if tag == TAGS['mask']:
        counts = []
        for t in body:
            if not (t.startswith('<r') and t.endswith('>')):
                raise ValueError('mask 块里出现非 RLE token: %r' % (t,))
            counts.append(int(t[2:-1]))
        return ('mask', tuple(counts))
    k_tok = None
    if tag == TAGS['polygon']:
        if not body or not (body[0].startswith('<k') and body[0].endswith('>')):
            raise ValueError('polygon 块必须以顶点数 token 开头')
        k_tok = int(body[0][2:-1])
        body = body[1:]
    nums = []
    for t in body:
        if not (t.startswith('<c') and t.endswith('>')):
            raise ValueError('坐标块里出现非坐标 token: %r' % (t,))
        nums.append(int(t[2:-1]))
    if len(nums) % 2:
        raise ValueError('%s 的坐标个数必须是偶数，实际 %d' % (tag, len(nums)))
    vals = [dequantize(q) for q in nums]
    if tag == TAGS['point']:
        if len(vals) != 2:
            raise ValueError('point 必须恰好 2 个坐标')
        return ('point', tuple(vals))
    if tag == TAGS['box']:
        if len(vals) != 4:
            raise ValueError('box 必须恰好 4 个坐标')
        return ('box', canon_box(vals))
    if k_tok != len(vals) // 2:
        raise ValueError('顶点数 token %r 与实际 %d 不符' % (k_tok, len(vals) // 2))
    pts = [(vals[k], vals[k + 1]) for k in range(0, len(vals), 2)]
    return ('polygon', canon_polygon(pts))


def decode(tokens):
    '''混合序列 -> (文本 token, 原语列表)，即约束解码之后的反解步骤。'''
    text, prims = [], []
    by_tag = {}
    for k in TAGS:
        by_tag[TAGS[k]] = k
    i = 0
    while i < len(tokens):
        t = tokens[i]
        if t in by_tag:
            body, i = _read_block(tokens, i + 1)
            prims.append(parse_prim(t, body))
        elif t == CLOSE:
            raise ValueError('多余的结束符 %s' % CLOSE)
        else:
            text.append(t)
            i += 1
    return text, prims


def budget(prims):
    '''token 预算：point 4、box 6、polygon 3+2K、mask 2+R（R 为 RLE 段数）。'''
    n = 0
    for kind, geom in prims:
        if kind == 'mask':
            n += 2 + len(geom)
        elif kind == 'polygon':
            n += 3 + 2 * len(geom)
        elif kind == 'box':
            n += 6
        elif kind == 'point':
            n += 4
        else:
            raise ValueError('未知原语类型: %r' % (kind,))
    return n


class BigramLM:
    '''玩具语言模型：p(x_t | x 的前缀) 只依赖上一个 token，用来演示统一 NLL。'''

    def __init__(self, alpha=0.5):
        self.alpha = alpha
        self.vocab = set()
        self.pair = {}
        self.uni = {}

    def fit(self, seqs):
        for s in seqs:
            prev = '<bos>'
            self.vocab.add(prev)
            for t in s:
                self.vocab.add(t)
                self.pair[(prev, t)] = self.pair.get((prev, t), 0) + 1
                self.uni[prev] = self.uni.get(prev, 0) + 1
                prev = t
            self.pair[(prev, '<eos>')] = self.pair.get((prev, '<eos>'), 0) + 1
            self.vocab.add('<eos>')

    def prob(self, prev, nxt):
        v = len(self.vocab)
        num = self.pair.get((prev, nxt), 0) + self.alpha
        den = self.uni.get(prev, 0) + self.alpha * v
        return num / den


def masked_nll(tokens, model, loss_mask=None):
    '''-sum_t m_t log p(x_t | x 的前缀)；loss_mask 用来跳过 prompt 段。'''
    total = 0.0
    kept = 0
    prev = '<bos>'
    for i, t in enumerate(tokens):
        if loss_mask is None or loss_mask[i]:
            total -= math.log(max(model.prob(prev, t), 1e-12))
            kept += 1
        prev = t
    return total, kept


def main():
    # 1) 量化误差上界 |c - dequantize(quantize(c))| <= 1/(2*(BINS-1))
    worst = 0.0
    for i in range(2001):
        for c in (i / 2000.0, 1.0 - i / 2000.0):
            worst = max(worst, abs(c - dequantize(quantize(c))))
    bound = 1.0 / (2 * (BINS - 1))
    tol = bound + 1e-12                      # 浮点往返留一点余量
    assert worst <= tol, (worst, bound)
    print('量化误差 max=%.3e，上界 1/(2(B-1))=%.3e，换到 1000 像素图是 %.2f px'
          % (worst, bound, worst * 1000))

    # 2) 规范形把等价写法收敛成 1 种：box 有 4 种角点顺序，K 边形有 2K 种写法
    box = (0.8, 0.7, 0.2, 0.1)
    orders = ((0, 1, 2, 3), (2, 1, 0, 3), (0, 3, 2, 1), (2, 3, 0, 1))
    assert len({canon_box(tuple(box[k] for k in o)) for o in orders}) == 1
    poly = ((0.4, 0.1), (0.9, 0.5), (0.4, 0.9), (0.1, 0.5))
    forms = set()
    for k in range(len(poly)):
        rot = poly[k:] + poly[:k]
        forms.add(canon_polygon(rot))
        forms.add(canon_polygon(tuple(reversed(rot))))
    print('多边形等价写法 %d 种，规范化后 %d 种' % (2 * len(poly), len(forms)))
    assert len(forms) == 1, forms

    # 3) 文本 + 四种原语的混合序列往返，长度与预算函数一致
    bits = [0, 0, 1, 1, 1, 0, 0, 0, 1]
    prims = [
        ('point', (0.1234, 0.8765)),
        ('box', (0.8, 0.7, 0.2, 0.1)),
        ('polygon', ((0.4, 0.1), (0.9, 0.5), (0.4, 0.9), (0.1, 0.5))),
        ('mask', rle_encode(bits)),
    ]
    seq = encode(['猫', '在', '左上'], prims)
    text, back = decode(seq)
    assert text == ['猫', '在', '左上'] and len(back) == 4
    assert len(seq) == 3 + budget(prims), (len(seq), budget(prims))
    assert abs(back[0][1][0] - 0.1234) <= tol and abs(back[0][1][1] - 0.8765) <= tol
    want_box = (0.2, 0.1, 0.8, 0.7)
    assert max(abs(a - b) for a, b in zip(back[1][1], want_box)) <= tol
    want_poly = canon_polygon(prims[2][1])
    assert len(back[2][1]) == len(want_poly)
    for got, want in zip(back[2][1], want_poly):
        assert max(abs(got[0] - want[0]), abs(got[1] - want[1])) <= tol
    assert rle_decode(back[3][1], len(bits)) == bits
    print('混合序列 %d token = 文本 3 + 原语 %d；mask RLE %s 只要 %d token，稠密栅格要 %d'
          % (len(seq), budget(prims), tuple(rle_encode(bits)),
             2 + len(rle_encode(bits)), 2 + len(bits)))

    # 4) 统一自回归 NLL：p(x) 是全部 token 的联合，loss_mask 只跳过 prompt 段
    lm = BigramLM(alpha=0.5)
    lm.fit([seq, encode(['狗', '在', '右下'], prims[:2])])
    nll_all, n_all = masked_nll(seq, lm)
    loss_mask = [False, False, False] + [True] * (len(seq) - 3)
    nll_ans, n_ans = masked_nll(seq, lm, loss_mask)
    assert n_all == len(seq) and n_ans == len(seq) - 3 and nll_ans <= nll_all
    print('统一 NLL：全序列 %.3f（%d token），只算答案段 %.3f（%d token）'
          % (nll_all, n_all, nll_ans, n_ans))

    # 5) 边界：越界坐标 clamp、截断序列被拒、退化多边形被拒、全 0/全 1 掩码
    assert quantize(-0.5) == 0 and quantize(1.5) == BINS - 1
    assert rle_decode(rle_encode([0] * 6), 6) == [0] * 6
    assert rle_decode(rle_encode([1] * 3), 3) == [1] * 3
    bad_seqs = [seq[:-1], ['<box>', '<c10>', '<c20>', '<c30>', CLOSE]]
    for bad in bad_seqs:
        try:
            decode(bad)
        except ValueError as exc:
            print('非法序列被拒绝: %s' % exc)
            continue
        raise AssertionError('非法输入应当报错: %r' % (bad,))
    try:
        canon_polygon(((0.1, 0.1), (0.1, 0.1), (0.2, 0.2)))
    except ValueError as exc:
        print('退化多边形被拒绝: %s' % exc)
    else:
        raise AssertionError('退化多边形应当报错')
    print('边界用例全部通过：clamp、截断、退化多边形、空白掩码')


if __name__ == '__main__':
    main()
